class Agent:
    def __init__(self, browser, book, run, *, prepare_only=False, clef: ClefClient | None = None):
        self.browser, self.book, self.run = browser, book, run
        self.prepare_only = prepare_only
        self.clef = clef
        self.calculation = None
        self.calculation_input = None
        self.notes = []
        self.done = False
        self.receipt = None
        self.partial = None
        self.log_secrets = []

    async def dispatch(self, name, args):
        if name == "browser":
            return await self.browser.act(**args)
        if name == "cite":
            return {"evidence_id": self.book.cite(**args)}
        if name == "resolve":
            return RESOLVERS[args["rule"]](**json.loads(args["arguments_json"]))
        if name == "decide":
            if self.clef is None:
                return {"error": "ClefUnavailable", "message": "Cloudflare Clef is not configured or CLEF_BASE_URL is missing"}
            images = []
            if args.get("include_screenshot"):
                page_idx = args.get("page", 0)
                img_res = await self.browser.act("screenshot", page=page_idx)
                if isinstance(img_res, dict) and "image_url" in img_res:
                    images.append(img_res["image_url"])
            q_type = args["question_type"]
            instructions = args["instructions"]
            q_body: dict = {"type": q_type, "instructions": instructions}
            if "criteria" in args and args["criteria"] is not None:
                q_body["criteria"] = args["criteria"]
            q_id = args.get("question_id", "decision")
            state = args.get("state", {})
            return await self.clef.decide(state=state, questions={q_id: q_body}, images=images)
        if name == "note":
            self.notes.append(args["text"])
            return {"saved": True}
        if name == "notebook":
            return {"facts": self.book.facts, "notes": self.notes}
        if name == "partial_submission":
            reference = args["tender_reference"]
            omitted = args["omitted_positions"]
            citations = args.get("evidence_ids", [])
            if not reference or not omitted or len(omitted) != len(set(omitted)):
                raise ValueError("Partial bid needs a reference and unique omitted positions")
            if citations:
                self.book.validate_references({"evidence_ids": citations})
            tender_origin = origin(self.run["submission"]["url"])
            tender_texts = [observation["text"] for observation in self.book.observations.values()
                            if origin(observation["url"]) == tender_origin]
            if not any(reference in text for text in tender_texts):
                raise ValueError("Observe the exact reference on a tender-portal page")
            if any(not any(position in text for text in tender_texts) for position in omitted):
                raise ValueError("Observe each omitted position on a tender-portal page")
            self.partial = {"tender_reference": reference, "omitted_positions": omitted,
                            "evidence_ids": citations}
            return {"status": "partial_bid_authorized", "omitted_positions": omitted,
                    "next": "Select bid, omit each unfinished position on the portal, verify the review list, sign with the mail TAN, then cite the receipt"}
        if name == "calculate":
            parsed = BidInput.model_validate(args)
            self.book.validate_references(parsed.model_dump())
            calculation = calculate_bid(parsed)
            import jsonschema
            answer = wire_answer(calculation["answer"])
            jsonschema.validate(answer, self.run["answer_schema"])
            if len(json.dumps(answer).encode()) > 65536:
                raise ValueError("Answer exceeds challenge size limit")
            self.calculation_input = parsed.model_dump(mode="json")
            self.calculation = calculation
            if self.prepare_only:
                self.done = True
            return calculation
        if name == "finish":
            observation = self.book.observations[args["observation_id"]]
            quote = args["receipt_quote"]
            if not quote.strip() or quote not in observation["text"]:
                raise ValueError("Receipt must quote an observed confirmation")
            if origin(observation["url"]) != origin(self.run["submission"]["url"]):
                raise ValueError("Receipt must come from the tender submission site")
            self.receipt = {"observation_id": args["observation_id"], "quote": quote}
            self.done = True
            return {"status": "receipt_recorded"}
        raise ValueError("Unknown tool")


class ModelClient:
    """Hosted Qwen3.8-Flash-Next Chat Completions interface through the configured Atira proxy."""
    def __init__(self, client, base_url, api_key, model=DEFAULT_QWEN_MODEL):
        self.client, self.base_url, self.api_key, self.model = client, base_url.rstrip("/"), api_key, model

    async def complete(self, messages, tools):
        import httpx
        for attempt in range(3):
            try:
                response = await self.client.post(self.base_url + "/chat/completions",
                    headers={"Authorization": f"Bearer {self.api_key}"},
                    json={"model": self.model, "messages": messages, "tools": tools,
                          "tool_choice": "auto", "parallel_tool_calls": False, "max_tokens": 8000},
                    timeout=120)
                response.raise_for_status()
                return response.json()
            except (httpx.TimeoutException, httpx.NetworkError, httpx.HTTPStatusError) as exc:
                retryable = not isinstance(exc, httpx.HTTPStatusError) or exc.response.status_code in {
                    408, 429, 500, 502, 503, 504}
                if not retryable or attempt == 2:
                    raise
                await asyncio.sleep(2 ** attempt)


"""Bounded browser actions selected by the model; connects only to supplied CDP browsers."""
from __future__ import annotations

import base64
import math
import io
import zipfile
from pathlib import Path
from urllib.parse import urlsplit

from .evidence import EvidenceBook

MAX_DOCUMENT = 20 * 1024 * 1024


def origin(url: str) -> str:
    parts = urlsplit(url)
    if parts.scheme not in {"http", "https"} or not parts.hostname or parts.username or parts.password:
        raise ValueError("Expected an HTTP(S) URL without embedded credentials")
    return f"{parts.scheme}://{parts.netloc.lower()}"


def document_text(payload: bytes, name: str, member: str | None = None) -> str:
    """Read one selected document; ZIP members are listed until the model selects one."""
    if len(payload) > MAX_DOCUMENT:
        raise ValueError("Document exceeds 20 MiB")
    if name.lower().endswith(".zip"):
        with zipfile.ZipFile(io.BytesIO(payload)) as archive:
            if member is None:
                return "ZIP members (select one with member):\n" + "\n".join(archive.namelist()[:500])
            info = archive.getinfo(member)
            if info.is_dir() or info.file_size > MAX_DOCUMENT or member.lower().endswith(".zip"):
                raise ValueError("Unsupported or oversized ZIP member")
            # Never extract to the filesystem; path traversal names are harmless here.
            return document_text(archive.read(info), member)
    if name.lower().endswith(".pdf") or payload.startswith(b"%PDF"):
        import pymupdf
        with pymupdf.open(stream=payload, filetype="pdf") as document:
            return "\n".join(f"[page {i + 1}]\n{page.get_text()}" for i, page in enumerate(document))
    if name.lower().endswith((".txt", ".csv", ".md", ".json", ".xml", ".html")):
        return payload.decode("utf-8-sig")
    raise ValueError("Unsupported document format; use browser rendering for this document")


class BrowserSession:
    def __init__(self, browsers, book: EvidenceBook, allowed_urls: list[str]):
        self.browsers, self.book = browsers, book
        self.origins = {origin(url) for url in allowed_urls}
        self.pages = []
        self.controls = {}
        self.observed_pages = {}
        self.generation = 0
        self.downloads = {}

    @classmethod
    async def connect(cls, playwright, endpoints: list[str], book: EvidenceBook, allowed_urls: list[str]):
        if not 1 <= len(endpoints) <= 4:
            raise ValueError("Supply between one and four existing CDP browsers")
        browsers = []
        for endpoint in endpoints:
            parsed = urlsplit(endpoint)
            if parsed.hostname not in {"localhost", "127.0.0.1", "::1"}:
                raise ValueError("CDP endpoints must be local")
            browsers.append(await playwright.chromium.connect_over_cdp(endpoint, timeout=15000))
        session = cls(browsers, book, allowed_urls)
        for browser in browsers:
            for context in browser.contexts:
                context.set_default_timeout(8000)
                context.set_default_navigation_timeout(15000)
                await context.route("**/*", session._route)
        return session

    async def _route(self, route):
        url = route.request.url
        try:
            allowed = origin(url) in self.origins
        except ValueError:
            allowed = url.startswith(("data:", "blob:", "about:"))
        await (route.continue_() if allowed else route.abort())

    def page_list(self):
        for browser in self.browsers:
            for context in browser.contexts:
                for page in context.pages:
                    if page not in self.pages:
                        self.pages.append(page)
        return [{"page": i, "url": p.url} for i, p in enumerate(self.pages) if not p.is_closed()]

    def page(self, index):
        self.page_list()
        if type(index) is not int or index < 0 or index >= len(self.pages) or self.pages[index].is_closed():
            raise ValueError("Unknown or closed page")
        return self.pages[index]

    async def observe(self, page_index: int, frame_index=0, offset=0, control_offset=0):
        page = self.page(page_index)
        if min(frame_index, offset, control_offset) < 0 or frame_index >= len(page.frames):
            raise ValueError("Invalid observation offset or frame")
        frame = page.frames[frame_index]
        text = await frame.locator("body").inner_text(timeout=8000)
        self.generation += 1
        # Observing one frame does not invalidate refs on unrelated tabs/frames.
        self.controls = {ref: selected for ref, selected in self.controls.items()
                         if selected[:2] != (page_index, frame_index)}
        controls = []
        control_selector = "a, button, input, textarea, select, [role=button], [role=tab], [role=checkbox]"
        dialogs = frame.locator("dialog[open], [role=dialog][aria-modal=true]")
        active_dialog = None
        for dialog_index in range(await dialogs.count() - 1, -1, -1):
            candidate = dialogs.nth(dialog_index)
            if await candidate.is_visible():
                active_dialog = candidate
                break
        locator = active_dialog.locator(control_selector) if active_dialog else frame.locator(control_selector)
        total = await locator.count()
        for index in range(control_offset, min(total, control_offset + 100)):
            item = locator.nth(index)
            if not await item.is_visible():
                continue
            handle = await item.element_handle()
            info = await handle.evaluate("""e => ({tag: e.tagName, type: e.getAttribute('type'),
                text: (e.innerText || e.textContent || '').slice(0, 500),
                label: e.getAttribute('aria-label') || (e.labels ? [...e.labels].map(x => x.innerText).join(' ') : ''),
                placeholder: e.getAttribute('placeholder'), name: e.getAttribute('name'),
                value: e.tagName === 'INPUT' && e.type !== 'password' ? e.value.slice(0, 300) : undefined,
                hasValue: e.tagName === 'INPUT' && e.type === 'password' ? !!e.value : undefined,
                href: e.getAttribute('href'), options: e.tagName === 'SELECT' ?
                [...e.options].map(x => ({value: x.value, text: x.text})) : undefined})""")
            ref = f"control-{self.generation}-{index}"
            self.controls[ref] = (page_index, frame_index, handle)
            controls.append({"ref": ref, **info})
        excerpt = text[offset:offset + 16000]
        observation = self.book.observe(frame.url, excerpt)
        self.observed_pages[observation] = page_index
        return {"observation_id": observation, "page": page_index, "url": frame.url, "text": excerpt,
                "active_dialog": (await active_dialog.inner_text())[:2000] if active_dialog else None,
                "text_length": len(text), "offset": offset, "controls": controls, "control_count": total,
                "frames": [{"frame": i, "url": f.url, "name": f.name} for i, f in enumerate(page.frames)],
                "pages": self.page_list()}

    async def act(self, operation: str, page: int | None = None, **args):
        if operation == "pages":
            return self.page_list()
        if operation == "new_tab":
            browser_index = args.get("browser", 0)
            if type(browser_index) is not int or not 0 <= browser_index < len(self.browsers):
                raise ValueError("Unknown browser")
            new = await self.browsers[browser_index].contexts[0].new_page()
            self.page_list()
            return {"page": self.pages.index(new), "pages": self.page_list(),
                    "next": "Navigate the new tab to a run-provided site URL"}
        if operation == "new_context":
            browser_index = args.get("browser", 0)
            if type(browser_index) is not int or not 0 <= browser_index < len(self.browsers):
                raise ValueError("Unknown browser")
            context = await self.browsers[browser_index].new_context()
            context.set_default_timeout(8000)
            context.set_default_navigation_timeout(15000)
            await context.route("**/*", self._route)
            new = await context.new_page()
            self.page_list()
            return {"page": self.pages.index(new), "pages": self.page_list(),
                    "next": "Fresh browser context has no prior login; navigate to a run-provided site URL"}
        if page is None:
            # A ref identifies its own observed page. Most model calls omit the
            # optional page argument, particularly after opening a new tab.
            ref = args.get("ref")
            if operation == "fill_fields" and isinstance(args.get("fields"), list) and args["fields"]:
                ref = args["fields"][0].get("ref") if isinstance(args["fields"][0], dict) else None
            page = self.controls[ref][0] if ref in self.controls else 0
        target = self.page(page)
        if operation == "observe":
            return await self.observe(page, args.get("frame", 0), args.get("offset", 0), args.get("control_offset", 0))
        if operation == "screenshot":
            return {"image_url": "data:image/png;base64," + base64.b64encode(await target.screenshot()).decode()}
"}}

