"""Independent arithmetic and provenance checks; never discovers business facts."""
from decimal import Decimal, ROUND_HALF_UP

from .browser import same_origin


def check_answer(answer, schema):
    import jsonschema
    jsonschema.validate(answer, schema)
    positions = answer.get("positions", [])
    keys = [row["position"] for row in positions]
    if len(keys) != len(set(keys)):
        raise ValueError("Duplicate bid positions")
    total = sum((Decimal(str(row["quantity"])) * Decimal(str(row["unit_price"]))
                 for row in positions), Decimal(0)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    if total != Decimal(str(answer["total_net"])):
        raise ValueError("Independent quantity × unit price total disagrees")
    if answer["decision"] == "no_bid" and (positions or total):
        raise ValueError("No-bid must have no positions and zero total")


def tender_observation(book, observation_id, submission_url, quote):
    observation = book.observations[observation_id]
    if not same_origin(observation["url"], submission_url):
        raise ValueError("Evidence must come from the tender submission site")
    if not quote.strip() or quote not in observation["text"]:
        raise ValueError("Evidence must quote an observed confirmation exactly")
    return observation

"""Local action journal and four independently refreshed browser previews."""
import asyncio
from datetime import datetime, timezone
import html
import json
from pathlib import Path


class Trace:
    def __init__(self, directory, secrets):
        self.directory = Path(directory)
        self.directory.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.secrets = secrets
        self.sequence = 0
        self.latest = {}

    def clean(self, value):
        if isinstance(value, dict):
            return {k: ("[REDACTED]" if k in {"value", "password", "tan", "token", "image_url"}
                        else self.clean(v)) for k, v in value.items()}
        if isinstance(value, list):
            return [self.clean(v) for v in value]
        if isinstance(value, str):
            for secret in sorted(set(self.secrets), key=len, reverse=True):
                if secret:
                    value = value.replace(secret, "[REDACTED]")
        return value

    def event(self, **data):
        record = self.clean({"at": datetime.now(timezone.utc).isoformat(), **data})
        path = self.directory / "actions.jsonl"
        with path.open("a") as stream:
            stream.write(json.dumps(record, ensure_ascii=False, default=str) + "\n")
        path.chmod(0o600)
        return record

    async def capture(self, browser, pages=None):
        self.sequence += 1
        for row in browser.page_list():
            if pages is not None and row["page"] not in pages:
                continue
            page = browser.page(row["page"])
            name = f"b{row['browser']}-p{row['page']}-{self.sequence:05}.png"
            try:
                async with asyncio.timeout(2):
                    await page.screenshot(path=str(self.directory / name), timeout=1800)
                (self.directory / name).chmod(0o600)
                self.latest[row["browser"]] = {**row, "image": name}
                self.event(kind="screenshot", **row, image=name)
            except Exception as exc:
                self.event(kind="screenshot_error", **row, error=type(exc).__name__)
        cards = []
        for index in range(len(browser.browsers)):
            row = self.latest.get(index)
            body = (f'<p>Page {row["page"]}: {html.escape(row["url"])}</p>'
                    f'<a href="{row["image"]}"><img src="{row["image"]}"></a>' if row else '<p>Awaiting capture</p>')
            cards.append(f'<section><h2>Browser {index + 1}</h2>{body}</section>')
        (self.directory / "browsers.html").write_text(
            '<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="3">'
            '<title>RFQ browser observations</title><style>body{font:14px system-ui;margin:16px;background:#eee}'
            'main{display:grid;grid-template-columns:1fr 1fr;gap:16px}section{background:white;padding:12px}'
            'img{width:100%}p{overflow-wrap:anywhere}</style><h1>RFQ browser observations</h1>'
            '<p>Latest captured states; browser numbers here are one-based. Action journal: actions.jsonl. '
            'Screenshots can contain business data and TANs; keep these artifacts private.</p><main>' + ''.join(cards) + '</main>')

