      tools: MCP_TOOLS.map(({ name, title, description, inputSchema, annotations }) => ({
        name,
        title,
        description,
        inputSchema,
        annotations: { title, ...annotations },
      })),
    }
  if (method === "tools/call") {
    const tool = MCP_TOOLS.find((candidate) => candidate.name === params.name)
    if (!tool) throw new McpError(-32602, `Unknown tool: ${params.name}`)
    const args = params.arguments ?? {}
    const invalid = checkArguments(tool, args)
    if (invalid) return { content: [mcpText(`Invalid arguments: ${invalid}.`)], isError: true }
    // progress for long calls (wait_for_run), when the client asked for it with a progress token
    const token = params._meta?.progressToken
    const call = {
      progress(progress, message) {
        if ((typeof token === "string" || typeof token === "number") && session.notify)
          session.notify("notifications/progress", { progressToken: token, progress, message })
      },
    }
    try {
      return { content: await tool.run(args, session, call) }
    } catch (error) {
      const message = error instanceof CliError ? error.message : `Unexpected error: ${error?.message ?? error}`
      return { content: [mcpText(message)], isError: true }
    }
  }
  throw new McpError(-32601, `Method not found: ${method}`)
}

